    public static function key(string $source):string{return 'conversation_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {$english=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$english?$translation:$source;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string
    {$text=isset(self::ENGLISH[$source])?($messages[self::key($source)]??$source):ContentMessages::text($source,$messages);$args=[];foreach($values as$key=>$value)$args['{'.$key.'}']=(string)$value;return strtr($text,$args);}
    public static function browser(array $messages):array
    {$out=[];foreach(['Instagram-Antwort ist zu lang. Bitte kürzen.']as$source)$out[$source]=self::text($source,$messages);return$out;}
}
